from datetime import datetime

def generate_business_report(df, info, insights, predictor_info=None):
    report_md = f"""# Executive Business Report
**Generated by Insightify AI**
Date: {datetime.now().strftime('%Y-%m-%d %H:%M')}

## 1. Executive Summary
The analyzed dataset contains **{info['Total Rows']:,} records** and **{info['Total Columns']:,} features**. 
Overall Data Quality Score sits at **{info['Data Quality Score']}%**, indicating the general completeness and uniqueness of the current data.

## 2. Key Insights
"""
    for idx, ins in enumerate(insights):
        report_md += f"- {ins}\n"
        
    report_md += f"\n## 3. Machine Learning Modeling\n"
    if predictor_info:
        report_md += f"A **{predictor_info['model_type']}** objective was automatically detected.\n"
        report_md += f"The system tested multiple models, and selected **{predictor_info['best_model_name']}** as the best performer, achieving a {predictor_info['score_metric']} of **{predictor_info['best_score']:.4f}**.\n\n"
        
        if predictor_info['feature_importance'] is not None:
            top_feat = predictor_info['feature_importance'].iloc[0]['Feature']
            report_md += f"- **Top driving feature:** `{top_feat}`\n"
            
        report_md += "\n### Model Comparison Metrics\n"
        ct = predictor_info['comparison_table']
        # Build markdown table manually (no tabulate dependency needed)
        report_md += "| " + " | ".join(ct.columns) + " |\n"
        report_md += "| " + " | ".join(["---"] * len(ct.columns)) + " |\n"
        for _, row in ct.iterrows():
            report_md += "| " + " | ".join(str(v) for v in row.values) + " |\n"
    else:
        report_md += "No predictive modeling was executed during this session.\n"
        
    report_md += """

## 4. Automated Recommendations
- **Data Cleanup**: Since Missing Percentage is """ + f"{info['Missing Percentage']}%, " + ("cleaning is highly recommended." if info['Missing Percentage'] > 5 else "the dataset is reliably populated.") + """
- **Action Steps**: Focus internal strategy on leveraging the top driven features and trends highlighted in the key insights above.

---
*Insightify AI Universal Analyzer Engine*
"""
    return report_md
